-- Reschedule a class from the calendar.
--
-- Timetable classes (auto = true) are regenerated by private.sync_sessions, so
-- simply moving one would be undone at the next sync. Instead the original row
-- stays in place marked `cancelled` (sync leaves it alone and won't recreate the
-- slot), and a one-off class is created at the new time. One-off classes are
-- just moved.

alter table public.sessions add column cancelled boolean not null default false;

create or replace function public.reschedule_session(p_session bigint, p_start timestamptz, p_duration int)
returns bigint
language plpgsql
security invoker            -- runs under the caller's RLS: only teachers can write sessions
set search_path = ''
as $$
declare
  s public.sessions;
  clash public.sessions;
  new_id bigint;
begin
  if not (select private.is_teacher()) then
    raise exception 'Only teachers can reschedule classes';
  end if;
  if p_duration not between 15 and 240 then
    raise exception 'Class length must be between 15 and 240 minutes';
  end if;

  select * into s from public.sessions where id = p_session and not cancelled for update;
  if not found then
    raise exception 'Class not found';
  end if;
  if s.starts_at + make_interval(mins => s.duration_min) <= now() then
    raise exception 'This class has already finished';
  end if;

  select * into clash from public.sessions
  where cohort_id = s.cohort_id and starts_at = p_start and id <> s.id;

  if found and clash.cancelled then
    -- moving back into a slot this class was moved out of: restore that slot
    update public.sessions set cancelled = false, duration_min = p_duration where id = clash.id;
    if s.auto then
      update public.sessions set cancelled = true where id = s.id;
    else
      delete from public.sessions where id = s.id;
    end if;
    return clash.id;
  elsif found then
    raise exception 'Another class already starts at that time';
  end if;

  if s.auto then
    update public.sessions set cancelled = true where id = s.id;
    insert into public.sessions (cohort_id, title, strand, unit, starts_at, duration_min, meet_url, auto)
    values (s.cohort_id, s.title, s.strand, s.unit, p_start, p_duration, s.meet_url, false)
    returning id into new_id;
    return new_id;
  end if;

  update public.sessions set starts_at = p_start, duration_min = p_duration where id = s.id;
  return s.id;
end;
$$;

revoke all on function public.reschedule_session(bigint, timestamptz, int) from public, anon;
grant execute on function public.reschedule_session(bigint, timestamptz, int) to authenticated;
